"""批次人工评审页面；沿用三档评审，不展示自动评分或生成推理。"""
PAGE = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>本批标题人工评审台</title>
<style>
:root{font:15px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#20252b;background:#f4f6f8}*{box-sizing:border-box}body{margin:0}header{background:white;border-bottom:1px solid #dce1e6;padding:14px 24px;display:flex;gap:16px;align-items:center;flex-wrap:wrap}h1{font-size:19px;margin:0}h2{font-size:17px;margin:0 0 12px}h3{font-size:15px}a{color:#245ca6}button,input,textarea,select{font:inherit}button{cursor:pointer;border:1px solid #b9c3ce;border-radius:6px;background:white;color:#20252b;padding:9px 15px}button:hover{background:#edf3fa}button.primary{background:#245ca6;color:white;border-color:#245ca6}button:disabled{opacity:.55;cursor:wait}button:focus-visible,a:focus-visible,textarea:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #68a3e9;outline-offset:2px}.layout{display:grid;grid-template-columns:280px minmax(0,1fr);min-height:calc(100vh - 64px)}aside{border-right:1px solid #dce1e6;background:white;padding:16px}.task{display:block;text-align:left;width:100%;padding:11px;margin-bottom:7px}.task.active{border-color:#245ca6;background:#eef4fb}.task small{display:block;color:#586675}.main{padding:24px;max-width:1050px;width:100%;margin:0 auto}.card{background:white;border:1px solid #dce1e6;border-radius:8px;padding:20px;margin-bottom:16px}.headline{font-size:24px;font-weight:650;line-height:1.45;margin:12px 0 18px}.muted{color:#586675}.row{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.pill{background:#edf1f5;border-radius:4px;padding:3px 8px;font-size:13px}.good{color:#17603b;background:#e6f4eb}.star{background:#fff8e6;border-color:#e0b64a}.star.on{background:#fdf0c8;border-color:#c9930f;font-weight:600}.pill.gold{color:#8a6100;background:#fdf3d7}.reason{border-left:3px solid #245ca6;padding-left:12px;white-space:pre-wrap}.disputed{border-left:4px solid #d97706;background:#fffbeb}.disputed table td{padding:4px 10px 4px 0;vertical-align:top}.disputed table td:first-child{color:#92400e;white-space:nowrap}.blocked{background:#fdf1ef;border-left:3px solid #c0392b;color:#8c2318;padding:7px 12px;margin:8px 0;font-size:13px;white-space:pre-wrap}.blocked b{color:#c0392b}.diagnostic{border-left:4px solid #6b7280;background:#fbfcfd}.diagnostic h2{margin-bottom:6px}.diagnostic .freeze-note{background:#eef2f7;border-left:3px solid #6b7280;padding:7px 12px;font-size:13px}#dialog-scope{background:#eef2f7;border-left:3px solid #6b7280;padding:7px 12px;font-size:13px;margin:8px 0}#dialog-scope:empty{display:none}.notice{padding:12px 20px;background:#fff8e9;border-bottom:1px solid #e8d9b5}.live{min-height:26px;margin-left:auto}.error{color:#9c2424}label{display:block;font-weight:600;margin:14px 0 5px}textarea,input,select{width:100%;border:1px solid #b9c3ce;border-radius:6px;padding:9px;background:white;color:#20252b}textarea{min-height:100px}dialog{width:min(580px,94vw);border:1px solid #c4cbd4;border-radius:10px;padding:24px}dialog::backdrop{background:#10182066}.actions{margin-top:20px;justify-content:flex-end}video{width:100%;max-height:440px;background:#111;border-radius:6px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.7 inherit}summary{cursor:pointer;font-weight:600;padding:8px 0}.frames{display:flex;gap:8px;overflow:auto}.frames img{max-width:220px;max-height:160px;object-fit:contain}.empty{padding:30px}.sticky{position:sticky;top:0}#feedback-dialog{width:min(880px,94vw)}@media(max-width:760px){.layout{display:block}aside{border-right:0;border-bottom:1px solid #dce1e6;max-height:260px;overflow:auto}.main{padding:14px}.headline{font-size:21px}header{padding:12px 14px}}
</style></head><body>
<header><h1>本批标题人工评审台</h1><span id="progress" class="muted">加载中</span><button id="feedbackButton">查看已保存反馈</button><span id="live" class="live" role="status" aria-live="polite"></span></header>
<div class="notice">你只需判断标题能不能用。「勉强通过／不可用」写一句具体问题；无需猜根因。意见保存到本批反馈账本，可在聊天中直接读取，不覆盖旧金标准。</div>
<div class="layout"><aside><div class="row"><h2>本批固定视频</h2><button id="refresh">刷新</button></div><div id="taskList"></div></aside><main class="main" id="content"><div class="empty">正在读取已有标题，不会重新生成。</div></main></div>
<dialog id="decision-dialog"><form id="decision-form"><h2 id="dialog-title">人工意见</h2><p id="dialog-headline"></p><p id="dialog-scope" class="freeze-note"></p><label for="verdict">判定</label><select id="verdict"><option value="approved">可用：原样就能用</option><option value="marginal">勉强通过：有局部瑕疵</option><option value="rejected">不可用：事实、看点或表达方向有问题</option></select><label for="reason">一句话意见 <span class="muted">（可用可留空，其他必填）</span></label><textarea id="reason" placeholder="例如：视频重点是长期训练，不是演示这个器械。"></textarea><label for="reason-type">问题类型（可选）</label><select id="reason-type"><option value="">不确定，留给 AI 分析</option value="fact">事实错误</option><option value="context">关键背景缺失</option><option value="point">没写到核心看点</option><option value="grammar">句子不完整</option><option value="unclear">用词读不懂</option><option value="other">其他</option></select><details><summary>可选：修改标题或填写判据</summary><label for="final-title">修改后的完整标题（含平台前缀，非必填）</label><input id="final-title" placeholder="留空表示不改写；只有确实要改时才填"><label for="criteria">判据 ID（可留空）</label><input id="criteria" placeholder="如 C19"><label for="reviewer">评审人</label><input id="reviewer" value="tiffany"></details><p id="form-error" class="error" role="alert"></p><div class="row actions"><button type="button" id="cancel">取消</button><button type="submit" class="primary" id="save">保存意见</button></div></form></dialog>
<dialog id="feedback-dialog"><h2>已保存的人工反馈</h2><p class="muted">这些记录已经落盘。回到聊天说「我评完了」或「读取目前意见」，即可分析，不需要复制文字。</p><pre id="feedback-content"></pre><div class="row actions"><button id="close-feedback">关闭</button></div></dialog>
<script>
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={approved:'可用',marginal:'勉强通过',rejected:'不可用'};
const consistencyNames={aligned:'两份读法一致',detail:'同一件事，一侧写得更全（详略差异）',missing_point:'同一件事，一侧漏了要点',contradiction:'两份读法互斥，不能同时成立'};
function tierText(ev){const t=(ev&&ev.tiers)||{};const ks=Object.keys(t);if(!ks.length)return '未引用任何证据';return ks.map(k=>k+'×'+t[k]).join('、')}
function statusLabel(c,dis){if(c.status==='recommended'&&!c.deliverable)return '候选判定为推荐，系统路由未交付';if(dis&&c.thesis_basis==='review'&&(c.status==='recommended'||c.status==='ready_for_human_review'))return '系统通过（按复核侧解读重出）';if(dis&&dis.resolution==='regenerated_on_review')return systemNames[c.status]||c.status||'系统状态未知';if(dis&&(c.status==='recommended'||c.status==='ready_for_human_review'))return '系统通过（解读有分歧，未推荐）';return systemNames[c.status]||c.status||'系统状态未知'}
const systemNames={recommended:'系统推荐候选',ready_for_human_review:'系统通过，待人工评审',needs_review:'未交付：待核',rewrite:'未交付：需重写',reject:'未交付：拒绝',rejected:'未交付：拒绝',blocked:'未交付：检查拦截',unreviewed:'系统评审未完成（仅生成结果）',unknown:'系统状态未知'};
let tasks=[],active=null,current=null,saving=false;
async function api(path,options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json','X-Batch-Review':'1',...(options.headers||{})}});const d=await r.json();if(!r.ok)throw Error(d.error||r.statusText);return d}
function message(text,error=false){$('live').textContent=text;$('live').className='live'+(error?' error':'')}
function renderList(){const done=tasks.filter(t=>t.review_status==='done').length,empty=tasks.filter(t=>t.review_status==='no_candidates').length,total=tasks.reduce((n,t)=>n+(t.candidate_count||0),0),diagnostic=tasks.reduce((n,t)=>n+(t.diagnostic_count||0),0),diagnosticDone=tasks.reduce((n,t)=>n+(t.diagnostic_reviewed||0),0);$('progress').textContent=`冻结评审完成 ${done}/${tasks.length-empty} 个有候选视频 · 冻结候选 ${total} 条 · 诊断候选 ${diagnostic} 条（已评 ${diagnosticDone}，不计进度） · ${empty} 个视频无冻结候选`;$('taskList').innerHTML=tasks.map(t=>`<button class="task ${active===t.task_id?'active':''}" data-task="${esc(t.task_id)}"><b>${esc(t.blind_id)} · ${esc(t.category)}</b><small>${esc(t.title)}</small><span class="pill">${esc(t.source_status||'状态未知')}</span><span class="pill">${t.review_status==='done'?'冻结候选已评':t.review_status==='no_candidates'?'无冻结候选':'待评'}</span>${t.diagnostic_count?`<span class="pill">诊断候选 ${t.diagnostic_count}${t.diagnostic_reviewed?'（已评 '+t.diagnostic_reviewed+'）':''}</span>`:''}${t.length_excluded_count?`<span class="pill">超长拦截 ${t.length_excluded_count}（只读）</span>`:''}</button>`).join('');document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>openTask(b.dataset.task))}
async function refresh(){const d=await api('/api/tasks');tasks=d.tasks;renderList()}
function media(task,kind,index=0){return '/api/media?task_id='+encodeURIComponent(task.task_id)+'&kind='+kind+'&index='+index}
function pendingLimits(c){const items=c.pending_limits||[];return items.length?`<p class="reason"><b>限定初步词法待核信号（不是机械判否，可能已由评审确认）</b>：${items.map(x=>esc((x.claim_id?x.claim_id+'｜':'')+(x.reason||'限定需要人工确认')+'｜要求：'+(x.limit||'未提供'))).join('；')}</p>`:''}
function explain(c){const iss=c.review_issues||[];if(!iss.length)return '';const brief=s=>{const t=String(s||'').split(/[。；;]/)[0];return t.length>56?t.slice(0,56)+'…':t};return `<details class="explain"><summary>评审侧意见</summary>${iss.map(x=>`<div class="reason">${esc(brief(x.text)||x.code)}</div>`).join('')}</details>`}
function render(task){const v=task.state.video||{},cs=task.state.candidates||[],dis=task.state.contract_disagreement||null;const regen=!!(dis&&dis.resolution==='regenerated_on_review');const disCard=dis?`<section class="card disputed"><div class="row"><h2>${regen?'⚠️ 两套解读不一致，已按复核侧重出一组候选':'⚠️ 两套独立解读不一致，系统不推荐任何一条'}</h2></div><p class="blocked">${regen?'生成侧与复核侧各自独立读同一条视频，主旨承诺对不上。复核侧引用了原始材料（上传者原文或原题），生成侧整组建在转写与推断上，系统因此按复核侧重选看点、重出一组候选，两组一起列在下面供你对照。这不等于复核侧一定对——以原视频为准。':'生成侧与复核侧各自独立读同一条视频，主旨承诺对不上，且两侧站在同样的证据地基上（没有一侧引用原始材料）。系统不替你裁定哪边对，也不按任何一侧重写——重写只是把一次猜测换成另一次猜测。请以原视频为准自己判断。'}</p><table><tr><td>生成侧解读</td><td>${esc(dis.generated_promise)}</td></tr><tr><td>复核侧解读</td><td>${esc(dis.review_promise)}</td></tr></table><p class="muted">必保语义重合度 ${esc(String(dis.semantics_overlap))}；核心承诺字面相似度 ${esc(String(dis.promise_similarity))}；证据来源：生成侧 ${esc(tierText(dis.generated_evidence))}；复核侧 ${esc(tierText(dis.review_evidence))}（source＝上传者原文，raw_*＝原始采集，model_derived_uncalibrated＝模型推断；引用不等于事实成立）</p>${(dis.relation&&dis.relation!=='unavailable')?'<p class="muted">语义判官判定：'+esc(consistencyNames[dis.relation]||dis.relation)+(dis.reconcile_point?'——'+esc(dis.reconcile_point):'')+((dis.reconcile_missing&&dis.reconcile_missing.length)||(dis.reconcile_missing_generated&&dis.reconcile_missing_generated.length)?'（'+(dis.reconcile_missing_generated&&dis.reconcile_missing_generated.length?'生成侧漏了：'+esc(dis.reconcile_missing_generated.join('；')):'')+(dis.reconcile_missing_generated&&dis.reconcile_missing_generated.length&&dis.reconcile_missing&&dis.reconcile_missing.length?'；':'')+(dis.reconcile_missing&&dis.reconcile_missing.length?'复核侧漏了：'+esc(dis.reconcile_missing.join('；')):'')+'）':''):''}${dis.declared_relation?'<p class="muted">复核员的判定：'+esc(consistencyNames[dis.declared_relation]||dis.declared_relation)+(dis.declared_contradiction_point?'——'+esc(dis.declared_contradiction_point):'')+'</p>':''}</section>`:'';const diagnostic=task.diagnostic_candidates||[];const excluded=task.length_excluded_candidates||[];const excludedHtml=excluded.length?`<section class="card"><h2>超长失败轨迹（只读）</h2><p>不进入人工评审，不计待评；历史意见只读保留。</p>${excluded.map(c=>`<div class="reason"><b>${esc(c.rendered_title)}</b><br>系统状态：${esc(c.status||'检查拦截')}；标题超过字数上限${c.slot_id?'；槽位：'+esc(c.slot_id):''}${c.decision?'<br>历史人工意见（只读）：'+esc(names[c.decision.decision]||c.decision.decision)+' '+esc(c.decision.reason||''):''}</div>`).join('')}</section>`:'';const diagnosticHtml=diagnostic.length?`<section class="card diagnostic"><h2>其他留存候选（诊断口径，可评）</h2><p class="freeze-note">这些候选不在本批冻结映射里（机械检查未通过，或不是冻结轮次的三槽交付）。可以在这里下三档判定与写意见，但只进诊断口径账本，<b>不计入冻结评审指标</b>，也不改变本批交付结论与冻结进度。</p>${diagnostic.map((c,i)=>{const d=c.decision;return `<div class="reason"><div class="row"><b>${esc(c.rendered_title)}</b><span class="pill ${d?'good':''}">${d?'诊断已评：'+esc(names[d.decision]||d.decision):'诊断待评'}</span></div><p class="muted">系统状态：${esc(systemNames[c.status]||c.status)}；槽位：${esc(c.slot_id||'未知')}；重写次数：${esc(c.generation_round??'未知')}</p><p class="muted">${esc((c.codes||[]).join('、'))} ${esc((c.blocking_reasons||[]).map(r=>r.code+'｜'+r.text).join('；'))}</p>${pendingLimits(c)}${d?`<p class="muted">已记录诊断意见：${esc(d.reason||'（未填）')}${d.final_headline&&d.final_headline!==d.original_headline?'；修改后：'+esc(d.final_headline):''}</p><div class="row"><button data-dedit="${i}">修改诊断意见</button><button data-dreopen="${i}">撤回诊断判定</button></div>`:`<div class="row"><button class="primary" data-dverdict="${i}|approved">可用</button><button data-dverdict="${i}|marginal">勉强通过</button><button data-dverdict="${i}|rejected">不可用</button></div>`}</div>`}).join('')}</section>`:'';const slotNames={source_rewrite:'原题重述',core_summary:'主旨概括',core_hook:'核心钩子'};const missing=Array.isArray(task.state.delivery_slots?.missing)?task.state.delivery_slots.missing:[];const asr=(v.asr_segments||[]).map(s=>`[${s.start??''}–${s.end??''}秒] ${s.text||''}`).join('\n');const ocr=(v.ocr_segments||[]).map(s=>`[${s.second??''}秒] ${s.text||''}`).join('\n');const url=String(v.url||'').startsWith('https://www.bilibili.com/')?v.url:'https://www.bilibili.com/video/'+encodeURIComponent(task.video_id);const frames=(v.asset_paths?.frames||[]).map((_,i)=>`<a href="${media(task,'frame',i)}" target="_blank" rel="noopener"><img loading="lazy" src="${media(task,'frame',i)}" alt="原始抽帧 ${i+1}"></a>`).join('');$('content').innerHTML=`<section class="card"><div class="row"><h2>${esc(task.blind_id)} · ${esc(task.category)}</h2><span class="pill">${cs.length?'候选分别评':excluded.length?'已产出但超长拦截':'无冻结可评候选'}</span></div>${missing.length?`<p class="muted">未交付槽位：${missing.map(s=>esc(slotNames[s]||s)).join('、')}（如有生成草稿，下方仍可评）</p>`:''}${(task.mechanical_dropped||[]).length?`<p class="muted">另有 ${task.mechanical_dropped.length} 条候选未通过硬约束检查（超字数、数值无据等），未纳入冻结人工评审；留存草稿在下方诊断区展示。</p>`:''}<p>任务状态：${esc(task.source_status)}；系统路由：${esc(task.system_route?.action||'无')}；原因：${esc(task.system_route?.reason||'无')}；失败节点：${esc(task.failure_checkpoint||'无')}；错误：${esc(typeof task.error==='object'?JSON.stringify(task.error):task.error||'无')}</p></section>${disCard}${cs.length?cs.map((c,i)=>{const d=c.decision;return `<div class="card"><div class="row"><b>候选 ${i+1}${c.slot_id?' · '+esc(slotNames[c.slot_id]||c.slot_id):''}</b>${c.thesis_basis==='review'?'<span class="pill disputed">按复核侧解读重出</span>':''}<span class="pill">${esc(statusLabel(c,dis))}</span><span class="pill ${d?'good':''}">${d?esc(names[d.decision]):'待评'}</span>${d&&d.highlight?'<span class="pill gold">★ 精彩</span>':''}</div><div class="headline">${esc(c.rendered_title||c.headline)}</div>${c.generation?`<div class="row"><span class="pill">${esc(c.generation.label)}</span>${c.generation.parent_title?`<span class="pill">上一版：${esc(c.generation.parent_title)}</span>`:''}</div>${(c.generation.parent_issues||[]).length?`<p class="muted">上一版被打回的原因：${c.generation.parent_issues.map(esc).join('；')}</p>`:''}`:''}${explain(c)}${c.blocking_reasons&&c.blocking_reasons.length?'<p class="blocked"><b>机械检查错误</b>（'+esc(String(c.title_length||''))+' 字）：'+c.blocking_reasons.map(r=>esc(r.code+'｜'+r.text)).join('；')+'</p>':''}${pendingLimits(c)}${d?`<p class="reason">${esc(d.reason||'已判可用')}</p>${d.final_headline&&d.final_headline!==d.original_headline?`<p>修改后：<b>${esc(d.final_headline)}</b></p>`:''}<div class="row"><button data-edit="${i}">修改意见</button><button data-reopen="${i}">撤回</button>${d.decision==='approved'?`<button class="${d.highlight?'star on':'star'}" data-highlight="${i}" data-on="${d.highlight?1:0}">${d.highlight?'★ 已标精彩':'☆ 标为精彩'}</button>`:''}</div>`:`<div class="row"><button class="primary" data-verdict="${i}|approved">可用</button><button data-verdict="${i}|marginal">勉强通过</button><button data-verdict="${i}|rejected">不可用</button><button class="star" data-highlight="${i}" data-on="0">☆ 精彩</button></div>`}</div>`}).join(''):'<p>该视频没有冻结可评候选；不代表没有生成草稿，请查看诊断候选。</p>'}${excludedHtml}${diagnosticHtml}<section class="card"><div class="row"><h2>原始视频材料</h2><a href="${esc(url)}" target="_blank" rel="noopener">在 B站打开原视频</a></div><video controls preload="metadata" src="${media(task,'video')}"></video><details><summary>完整 ASR 与 OCR</summary><p class="muted">机器提取可能有误；以原视频为准，不用模型描述当事实。</p><h3>ASR</h3><pre>${esc(asr||'（无 ASR）')}</pre><h3>OCR</h3><pre>${esc(ocr||'（无 OCR）')}</pre></details><details><summary>查看原始抽帧</summary><div class="frames">${frames||'（无抽帧）'}</div></details><details><summary>原始标题（需要时再看）</summary><p>${esc(v.title||'')}</p></details></section><p class="muted">已提交的意见可随时修改或撤回；不会改变这批生成结果。</p>`;document.querySelectorAll('[data-verdict]').forEach(b=>{const[i,v]=b.dataset.verdict.split('|');b.onclick=()=>openDecision(parseInt(i),v)});document.querySelectorAll('[data-highlight]').forEach(b=>b.onclick=()=>openDecision(parseInt(b.dataset.highlight),'approved',b.dataset.on!=='1'));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const c=current.state.candidates[parseInt(b.dataset.edit)];openDecision(parseInt(b.dataset.edit),c.decision.decision)});document.querySelectorAll('[data-reopen]').forEach(b=>b.onclick=()=>reopen(parseInt(b.dataset.reopen)));document.querySelectorAll('[data-dverdict]').forEach(b=>{const[i,v]=b.dataset.dverdict.split('|');b.onclick=()=>openDecision(parseInt(i),v,false,'diagnostic')});document.querySelectorAll('[data-dedit]').forEach(b=>b.onclick=()=>{const c=current.diagnostic_candidates[parseInt(b.dataset.dedit)];openDecision(parseInt(b.dataset.dedit),c.decision.decision,false,'diagnostic')});document.querySelectorAll('[data-dreopen]').forEach(b=>b.onclick=()=>reopen(parseInt(b.dataset.dreopen),'diagnostic'))}
async function openTask(id){try{const d=await api('/api/task?task_id='+encodeURIComponent(id));active=id;current=d.task;render(current);renderList()}catch(e){message(e.message,true)}}
let currentCandidate=null,pendingHighlight=false,currentScope='frozen';function openDecision(index,verdict,highlight,scope){if(saving||!current)return;currentScope=scope==='diagnostic'?'diagnostic':'frozen';$('decision-form').reset();pendingHighlight=!!highlight&&currentScope==='frozen';$('verdict').value=pendingHighlight?'approved':verdict;$('verdict').disabled=pendingHighlight;const list=currentScope==='diagnostic'?(current.diagnostic_candidates||[]):(current.state.candidates||[]);const c=list[index],d=c?c.decision:null;currentCandidate=c;$('dialog-title').textContent=currentScope==='diagnostic'?'人工意见（诊断口径）':(pendingHighlight?'标为精彩（同时记为可用）':'人工意见');$('dialog-scope').textContent=currentScope==='diagnostic'?'这是诊断候选：判定只进诊断口径账本，不计入冻结评审指标，也不改变本批冻结进度。':'';$('dialog-headline').textContent=c?c.rendered_title||c.headline:'';$('reason').value=d?.reason||'';$('reason').placeholder=currentScope==='diagnostic'?'例如：这条为什么没交付／值不值得重写（不计入冻结指标）。':(pendingHighlight?'好在哪（可选）：这句会进案例库，作为同类标题的正面示范':'例如：视频重点是长期训练，不是演示这个器械。');$('final-title').value=d?.final_headline||'';$('reason-type').value=d?.reason_type||'';$('criteria').value=d?.criteria_id||'';$('reviewer').value=d?.reviewer||'tiffany';$('form-error').textContent='';$('decision-dialog').showModal();$('reason').focus()}
$('decision-form').onsubmit=async e=>{e.preventDefault();if(saving)return;const verdict=$('verdict').value,reason=$('reason').value.trim();if(verdict!=='approved'&&!reason){$('form-error').textContent='请写一句具体问题；不要求给改写方案。';$('reason').focus();return}const task=current,c=currentCandidate;saving=true;$('save').disabled=true;$('form-error').textContent='';message('正在保存…');try{await api('/api/decision',{method:'POST',body:JSON.stringify({task_id:task.task_id,candidate_id:c.candidate_id,title_hash:c.title_hash,slot_id:c.slot_id,scope:currentScope,decision:verdict,reason,final_headline:$('final-title').value,criteria_id:$('criteria').value.trim(),reason_type:$('reason-type').value,reviewer:$('reviewer').value.trim(),highlight:pendingHighlight})});pendingHighlight=false;$('decision-dialog').close();await refresh();await openTask(task.task_id);message(currentScope==='diagnostic'?'已保存到诊断口径账本（不计入冻结评审指标）':'已保存到本批反馈账本');const savedTask=tasks.find(t=>t.task_id===task.task_id);if(savedTask?.review_status==='done'){const next=tasks.find(t=>t.review_status==='unreviewed');if(next)await openTask(next.task_id)}}catch(err){$('form-error').textContent=err.message;message('未保存，请修正后重试',true)}finally{saving=false;$('save').disabled=false}};
async function reopen(index,scope){const diagnostic=scope==='diagnostic';if(!confirm(diagnostic?'撤回这条诊断判定？历史操作保留，标题不变。':'撤回这条判定？历史操作保留，标题不变。'))return;try{const task=current,list=diagnostic?(current.diagnostic_candidates||[]):(current.state.candidates||[]),c=list[index];await api('/api/decision',{method:'POST',body:JSON.stringify({task_id:task.task_id,candidate_id:c.candidate_id,title_hash:c.title_hash,slot_id:c.slot_id,scope:diagnostic?'diagnostic':'frozen',decision:'reopen'})});await refresh();await openTask(task.task_id);message('已撤回，可重新评审')}catch(e){message(e.message,true)}}
$('feedbackButton').onclick=async()=>{try{const f=await api('/api/feedback');const format=d=>`${d.blind_id||d.task_id||'未知视频'} ${names[d.decision]||d.decision||'未知判定'}${d.highlight?'【精彩】':''}\n标题：${d.original_headline||d.headline||'（无标题）'}\n意见：${d.reason||'（无补充）'}${d.final_headline&&d.final_headline!==d.original_headline?'\n修改后：'+d.final_headline:''}`;const currentFeedback=(f.decisions||[]).map(format).join('\n\n')||'还没有保存新意见。';const diagnosticFeedback=(f.diagnostic_decisions||[]).map(d=>'[诊断口径] '+format(d)).join('\n\n')||'无诊断口径意见。';const legacy=(f.legacy_decisions_read_only||[]).map(format).join('\n\n')||'无旧记录。';$('feedback-content').textContent=`本批新意见（冻结口径，计入冻结评审指标）\n${currentFeedback}\n\n诊断口径意见（不计入冻结评审指标）\n${diagnosticFeedback}\n\n旧人工意见（只读，不计入当前进度）\n${legacy}`;$('feedback-dialog').showModal()}catch(e){message(e.message,true)}};
$('close-feedback').onclick=()=>$('feedback-dialog').close();$('cancel').onclick=()=>$('decision-dialog').close();$('refresh').onclick=async()=>{try{await refresh();if(active)await openTask(active);message('已刷新')}catch(e){message(e.message,true)}};
(async()=>{try{await refresh();const id=new URLSearchParams(location.search).get('task_id');await openTask(id&&tasks.some(t=>t.task_id===id)?id:(tasks.find(t=>t.review_status==='unreviewed')||tasks[0]).task_id);message('本机已连接')}catch(e){message(e.message,true)}})();
</script></body></html>'''
